-- Preflight (READ-ONLY) ก่อน apply ชุด three-tasks: 057 → 061 → 062 → 063 → 064 → 065 → 066 → 067 → 068
-- ใช้: sudo -u postgres psql -d <db> -X -f scripts/ops/preflight-three-tasks-migrations.sql
-- ไม่มีคำสั่งเขียนใด ๆ · ทุกแถว prereq ต้องเป็น ok=t ก่อนเริ่ม apply
\pset footer off
SELECT 'prereq' AS kind, x.name, x.ok FROM (VALUES
  ('table app_users',               to_regclass('public.app_users') IS NOT NULL),
  ('col app_users.bonus_scans',     EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='app_users' AND column_name='bonus_scans')),
  ('col app_users.created_at',      EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='app_users' AND column_name='created_at')),
  ('table app_settings',            to_regclass('public.app_settings') IS NOT NULL),
  ('table scan_jobs',               to_regclass('public.scan_jobs') IS NOT NULL),
  ('col scan_jobs.access_source',   EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='scan_jobs' AND column_name='access_source')),
  ('table scan_uploads',            to_regclass('public.scan_uploads') IS NOT NULL),
  ('uq_scan_uploads_line_message',  to_regclass('public.uq_scan_uploads_line_message') IS NOT NULL),
  ('table outbound_messages',       to_regclass('public.outbound_messages') IS NOT NULL),
  ('col outbound.related_job_id',   EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='outbound_messages' AND column_name='related_job_id')),
  ('col outbound.related_payment_id', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='outbound_messages' AND column_name='related_payment_id')),
  ('table payments',                to_regclass('public.payments') IS NOT NULL),
  ('role web_anon',                 EXISTS (SELECT 1 FROM pg_roles WHERE rolname='web_anon')),
  ('role service_role',             EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role')),
  ('055 claim_paid_scan_decrement', to_regproc('public.claim_paid_scan_decrement') IS NOT NULL),
  ('058 notification_preferences',  to_regclass('public.notification_preferences') IS NOT NULL),
  ('060 migrate_daily_pick_optout', to_regproc('public.migrate_daily_pick_optout_if_absent') IS NOT NULL),
  ('no approve_notify dup (062 uq)', NOT EXISTS (SELECT 1 FROM public.outbound_messages WHERE kind='approve_notify' AND related_payment_id IS NOT NULL GROUP BY related_payment_id HAVING count(*)>1))
) AS x(name, ok)
UNION ALL
SELECT 'applied', y.name, y.ok FROM (VALUES
  ('057 new_customer_trial_status',  to_regproc('public.new_customer_trial_status') IS NOT NULL),
  ('057 scan_jobs.free_access_kind', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='scan_jobs' AND column_name='free_access_kind')),
  ('061 telegram_approval_tokens',   to_regclass('public.telegram_approval_tokens') IS NOT NULL),
  ('062 payment_entitlement_grants', to_regclass('public.payment_entitlement_grants') IS NOT NULL),
  ('063 approve(…,jsonb) only',      (SELECT count(*) FROM pg_proc WHERE proname='approve_payment_and_grant') = 1
                                     AND EXISTS (SELECT 1 FROM pg_proc WHERE proname='approve_payment_and_grant' AND pg_get_function_identity_arguments(oid) LIKE '%jsonb')),
  ('064 release_bonus_reservation',  to_regproc('public.release_bonus_reservation') IS NOT NULL),
  ('064 dup-evidence trigger',       EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='trg_release_bonus_on_dup_evidence')),
  ('064 trial_used excludes bonus%', COALESCE(pg_get_functiondef(to_regproc('public.new_customer_trial_used')) LIKE '%NOT LIKE ''bonus%''%', false)),
  ('065 trial_used ignores delivery status (dup evidence counts when recorded)', COALESCE(pg_get_functiondef(to_regproc('public.new_customer_trial_used')) NOT LIKE '%o.status = ''sent''%', false)),
  ('066 telegram_approval_settings table', to_regclass('public.telegram_approval_settings') IS NOT NULL),
  ('066 role telegram_config_admin',       EXISTS (SELECT 1 FROM pg_roles WHERE rolname='telegram_config_admin')),
  ('066 RPCs present (4)',                 (SELECT count(*) FROM pg_proc WHERE proname IN ('telegram_settings_get_public','telegram_settings_get_secrets','telegram_settings_save','telegram_settings_set_enabled')) = 4),
  -- ต้องรันได้ทั้งก่อน/หลัง apply 066: role/ตาราง/ฟังก์ชันอาจยังไม่มี → ใช้ CASE/regclass/query_to_xml ไม่อ้างชื่อตรง
  ('066 web_anon cannot EXECUTE config RPCs', NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname LIKE 'telegram_settings_%' AND (has_function_privilege('web_anon', p.oid, 'EXECUTE') OR has_function_privilege('service_role', p.oid, 'EXECUTE')))),
  ('066 only telegram_config_admin can EXECUTE', CASE WHEN EXISTS (SELECT 1 FROM pg_roles WHERE rolname='telegram_config_admin') THEN (SELECT count(*) FROM pg_proc p WHERE p.proname LIKE 'telegram_settings_%' AND has_function_privilege('telegram_config_admin', p.oid, 'EXECUTE')) = 4 ELSE false END),
  ('066 table not readable by web_anon/service_role', to_regclass('public.telegram_approval_settings') IS NOT NULL AND NOT (COALESCE(has_table_privilege('web_anon', to_regclass('public.telegram_approval_settings'), 'SELECT'), false) OR COALESCE(has_table_privilege('service_role', to_regclass('public.telegram_approval_settings'), 'SELECT'), false))),
  ('066 enabled=false (ยังไม่เปิด)',        CASE WHEN to_regclass('public.telegram_approval_settings') IS NULL THEN true
                                              ELSE COALESCE((SELECT (xpath('/row/enabled/text()', query_to_xml('select coalesce((select enabled from public.telegram_approval_settings where id=1), false) as enabled', true, true, '')))[1]::text::boolean), false) = false END),
  -- 067 (free policy 3 โหมด + ตั้งเวลา): รันได้ทั้งก่อน/หลัง apply · ก่อน apply แถว 067 เป็น f ตามคาด ยกเว้นแถวความสอดคล้องสวิตช์/no pending (t)
  ('067 free_policy setting present',      EXISTS (SELECT 1 FROM public.app_settings WHERE key='free_policy')),
  ('067 switches consistent (ไม่เปิดสองตัวพร้อมกัน)', NOT (COALESCE((SELECT (value->>'enabled')::boolean FROM public.app_settings WHERE key='new_customer_trial'), false) AND COALESCE((SELECT (value->>'daily_enabled')::boolean FROM public.app_settings WHERE key='free_policy'), false))),
  ('067 schedule + audit tables',          to_regclass('public.free_policy_schedule') IS NOT NULL AND to_regclass('public.free_policy_audit') IS NOT NULL),
  ('067 role free_policy_admin',           EXISTS (SELECT 1 FROM pg_roles WHERE rolname='free_policy_admin')),
  ('067 telegram_config_admin inherits free_policy_admin (key เดิมใช้ได้)', CASE WHEN EXISTS (SELECT 1 FROM pg_roles WHERE rolname='telegram_config_admin') AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname='free_policy_admin') THEN pg_has_role('telegram_config_admin','free_policy_admin','MEMBER') ELSE false END),
  ('067 RPCs present (11)',                (SELECT count(*) FROM pg_proc WHERE proname IN ('free_policy_stored_mode','free_policy_mode_now','free_policy_status','free_policy_notice_check','free_policy_apply_internal','set_free_policy_mode','free_policy_schedule_set','free_policy_schedule_cancel','free_policy_reconcile_due','free_policy_schedule_apply_due','free_policy_audit_recent')) = 11),
  ('067 web_anon/service_role cannot EXECUTE mutating RPCs (รวม set_new_customer_trial_policy)', to_regproc('public.set_free_policy_mode') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname IN ('set_free_policy_mode','free_policy_schedule_set','free_policy_schedule_cancel','free_policy_schedule_apply_due','free_policy_reconcile_due','free_policy_apply_internal','free_policy_audit_recent','set_new_customer_trial_policy') AND (has_function_privilege('web_anon', p.oid, 'EXECUTE') OR has_function_privilege('service_role', p.oid, 'EXECUTE')))),
  ('067 web_anon can read status RPCs',    CASE WHEN to_regproc('public.free_policy_status') IS NULL THEN false ELSE has_function_privilege('web_anon', to_regproc('public.free_policy_status'), 'EXECUTE') AND has_function_privilege('web_anon', to_regproc('public.new_customer_trial_status'), 'EXECUTE') END),
  ('067 internal RPCs not executable by free_policy_admin', CASE WHEN EXISTS (SELECT 1 FROM pg_roles WHERE rolname='free_policy_admin') THEN NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname IN ('free_policy_apply_internal','free_policy_reconcile_due') AND has_function_privilege('free_policy_admin', p.oid, 'EXECUTE')) ELSE false END),
  ('067 tables not readable by web_anon/service_role', to_regclass('public.free_policy_schedule') IS NOT NULL AND NOT (COALESCE(has_table_privilege('web_anon', to_regclass('public.free_policy_schedule'), 'SELECT'), false) OR COALESCE(has_table_privilege('service_role', to_regclass('public.free_policy_schedule'), 'SELECT'), false) OR COALESCE(has_table_privilege('web_anon', to_regclass('public.free_policy_audit'), 'SELECT'), false))),
  ('067 no pending schedule (ยังไม่ตั้งเวลา)', CASE WHEN to_regclass('public.free_policy_schedule') IS NULL THEN true
                                              ELSE COALESCE((SELECT (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.free_policy_schedule where status=''pending''', true, true, '')))[1]::text::int), 0) = 0 END),
  ('067 guard trigger uses effective mode (free_policy_mode_now)', COALESCE(pg_get_functiondef(to_regproc('public.guard_new_customer_trial_job')) LIKE '%free_policy_mode_now%', false)),
  ('067 app_settings guard trigger present (กันแก้นโยบายตรง)', EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname='app_settings' AND t.tgname='trg_guard_free_policy_settings' AND NOT t.tgisinternal)),
  ('067 RPCs present (13 incl. lock/guard)', (SELECT count(*) FROM pg_proc WHERE proname IN ('free_policy_lock','guard_free_policy_settings')) = 2),
  ('067 lock/guard not executable by web_anon/service_role/free_policy_admin', to_regproc('public.free_policy_lock') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname IN ('free_policy_lock','guard_free_policy_settings') AND (has_function_privilege('web_anon', p.oid, 'EXECUTE') OR has_function_privilege('service_role', p.oid, 'EXECUTE') OR (EXISTS (SELECT 1 FROM pg_roles WHERE rolname='free_policy_admin') AND has_function_privilege('free_policy_admin', p.oid, 'EXECUTE'))))),
  ('067 guard is SECURITY INVOKER + owner check (ไม่เชื่อ GUC อย่างเดียว)', COALESCE((SELECT NOT prosecdef AND prosrc LIKE '%proowner%' FROM pg_proc WHERE proname='guard_free_policy_settings' LIMIT 1), false)),
  ('067 mutating RPCs decide with post-lock clock_timestamp', COALESCE(pg_get_functiondef(to_regproc('public.free_policy_schedule_cancel')) LIKE '%clock_timestamp()%', false) AND COALESCE(pg_get_functiondef(to_regproc('public.free_policy_schedule_set')) LIKE '%clock_timestamp()%', false) AND COALESCE(pg_get_functiondef(to_regproc('public.set_free_policy_mode')) LIKE '%clock_timestamp()%', false)),
  -- 068 admin alert outbox (Telegram-only admin alerts, 19 ต.ค. 2026): รันได้ก่อน/หลัง apply
  ('068 admin_alert_outbox table',          to_regclass('public.admin_alert_outbox') IS NOT NULL),
  ('068 RPCs present (3: enqueue/claim/finish)', (SELECT count(*) FROM pg_proc WHERE proname IN ('admin_alert_outbox_enqueue','admin_alert_outbox_claim','admin_alert_outbox_finish')) = 3),
  ('068 web_anon has NO privilege on outbox table/RPCs (Codex รอบ 2)', to_regclass('public.admin_alert_outbox') IS NOT NULL AND NOT has_table_privilege('web_anon', to_regclass('public.admin_alert_outbox'), 'SELECT') AND NOT has_table_privilege('web_anon', to_regclass('public.admin_alert_outbox'), 'INSERT') AND NOT has_table_privilege('web_anon', to_regclass('public.admin_alert_outbox'), 'UPDATE') AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname IN ('admin_alert_outbox_enqueue','admin_alert_outbox_claim','admin_alert_outbox_finish') AND has_function_privilege('web_anon', p.oid, 'EXECUTE'))),
  ('068 role admin_alert_writer EXECUTE on 3 RPCs, no direct table write', EXISTS (SELECT 1 FROM pg_roles WHERE rolname='admin_alert_writer') AND (SELECT count(*) FROM pg_proc p WHERE p.proname IN ('admin_alert_outbox_enqueue','admin_alert_outbox_claim','admin_alert_outbox_finish') AND has_function_privilege('admin_alert_writer', p.oid, 'EXECUTE')) = 3 AND NOT has_table_privilege('admin_alert_writer', to_regclass('public.admin_alert_outbox'), 'INSERT')),
  ('068 dedupe partial unique index',       to_regclass('public.uq_admin_alert_outbox_dedupe_pending') IS NOT NULL),
  -- 069 Telegram reject + settlement (20 ต.ค. 2026): รันได้ก่อน/หลัง apply
  ('069 RPCs present (5: reject token / reject atomic / settlement resolve / notify queued+list)', (SELECT count(*) FROM pg_proc WHERE proname IN ('issue_telegram_reject_token','reject_payment_atomic','payment_settlement_resolve','mark_reject_notify_queued','list_reject_notify_pending')) = 5),
  ('069 write RPCs only for payment_ops_writer (web_anon/service_role denied)', EXISTS (SELECT 1 FROM pg_roles WHERE rolname='payment_ops_writer') AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname IN ('reject_payment_atomic','payment_settlement_resolve','mark_reject_notify_queued','list_reject_notify_pending') AND (has_function_privilege('web_anon', p.oid, 'EXECUTE') OR has_function_privilege('service_role', p.oid, 'EXECUTE'))) AND (SELECT count(*) FROM pg_proc p WHERE p.proname IN ('reject_payment_atomic','payment_settlement_resolve','mark_reject_notify_queued','list_reject_notify_pending') AND has_function_privilege('payment_ops_writer', p.oid, 'EXECUTE')) = 4),
  ('069 payments.settlement_status/reject_notify_pending + token.reject_reason_code', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='payments' AND column_name='settlement_status') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='payments' AND column_name='reject_notify_pending') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='telegram_approval_tokens' AND column_name='reject_reason_code')),
  ('069 token kind check allows reject_confirm', COALESCE((SELECT pg_get_constraintdef(oid) LIKE '%reject_confirm%' FROM pg_constraint WHERE conname='telegram_approval_tokens_kind_check'), false)),
  -- 069 รอบ 3: snapshot ข้อความแจ้ง + unique 1 แถว reject_notify ต่อ payment + list คืน snapshot
  ('069r3 payments.reject_notify_snapshot + unique index uq_outbound_reject_notify_per_payment', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='payments' AND column_name='reject_notify_snapshot') AND EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='uq_outbound_reject_notify_per_payment' AND indexdef LIKE '%UNIQUE%' AND indexdef LIKE '%reject_notify%')),
  ('069r3 list_reject_notify_pending returns reject_notify_snapshot', EXISTS (SELECT 1 FROM pg_proc WHERE proname='list_reject_notify_pending' AND pg_get_function_result(oid) LIKE '%reject_notify_snapshot jsonb%')),
  ('067 set_free_policy_mode locks before reading (free_policy_lock)', COALESCE(pg_get_functiondef(to_regproc('public.set_free_policy_mode')) LIKE '%free_policy_lock()%', false) AND COALESCE(pg_get_functiondef(to_regproc('public.free_policy_schedule_cancel')) LIKE '%schedule_already_effective%', false)),
  -- Codex 30 ก.ย.: md5(prosrc) พิสูจน์แค่ body — ตรวจ definition ที่เหลือด้วย: SECURITY DEFINER, search_path, grants, trigger เปิด
  ('fn: all SECURITY DEFINER',       (SELECT count(*) FROM pg_proc p WHERE p.proname = ANY(ARRAY['new_customer_trial_status','new_customer_trial_used','set_new_customer_trial_policy','guard_new_customer_trial_job','issue_telegram_approval_token','consume_telegram_approval_token','record_payment_approval_audit','purge_expired_telegram_approval_tokens','approve_payment_and_grant','list_payment_grants_pending_notify','mark_payment_grant_notified','release_bonus_reservation','release_bonus_on_dup_evidence','sweep_bonus_releases','telegram_settings_get_public','telegram_settings_get_secrets','telegram_settings_save','telegram_settings_set_enabled']) AND NOT p.prosecdef) = 0
                                     AND (SELECT count(*) FROM pg_proc p WHERE p.proname = ANY(ARRAY['new_customer_trial_status','new_customer_trial_used','set_new_customer_trial_policy','guard_new_customer_trial_job','issue_telegram_approval_token','consume_telegram_approval_token','record_payment_approval_audit','purge_expired_telegram_approval_tokens','approve_payment_and_grant','list_payment_grants_pending_notify','mark_payment_grant_notified','release_bonus_reservation','release_bonus_on_dup_evidence','sweep_bonus_releases','telegram_settings_get_public','telegram_settings_get_secrets','telegram_settings_save','telegram_settings_set_enabled'])) = 18),
  ('fn: search_path pinned (public)', (SELECT count(*) FROM pg_proc p WHERE p.proname = ANY(ARRAY['new_customer_trial_status','new_customer_trial_used','set_new_customer_trial_policy','guard_new_customer_trial_job','issue_telegram_approval_token','consume_telegram_approval_token','record_payment_approval_audit','purge_expired_telegram_approval_tokens','approve_payment_and_grant','list_payment_grants_pending_notify','mark_payment_grant_notified','release_bonus_reservation','release_bonus_on_dup_evidence','sweep_bonus_releases','telegram_settings_get_public','telegram_settings_get_secrets','telegram_settings_save','telegram_settings_set_enabled']) AND NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%public%')) = 0),
  ('fn: PUBLIC has no EXECUTE',       (SELECT count(*) FROM pg_proc p WHERE p.proname = ANY(ARRAY['new_customer_trial_status','set_new_customer_trial_policy','consume_telegram_approval_token','issue_telegram_approval_token','approve_payment_and_grant','list_payment_grants_pending_notify','mark_payment_grant_notified','release_bonus_reservation','sweep_bonus_releases']) AND has_function_privilege('public', p.oid, 'EXECUTE')) = 0),
  ('fn: service_role can EXECUTE RPCs', (SELECT count(*) FROM pg_proc p WHERE p.proname = ANY(ARRAY['new_customer_trial_status','consume_telegram_approval_token','approve_payment_and_grant','list_payment_grants_pending_notify','mark_payment_grant_notified','release_bonus_reservation','sweep_bonus_releases']) AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')) = 0),
  ('trigger 057/064 enabled',         (SELECT count(*) FROM pg_trigger WHERE tgname IN ('guard_new_customer_trial_job','trg_release_bonus_on_dup_evidence') AND tgenabled = 'O') = 2),
  ('trigger guard on scan_jobs INSERT+UPDATE OF status', EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE t.tgname='guard_new_customer_trial_job' AND c.relname='scan_jobs' AND pg_get_triggerdef(t.oid) LIKE '%BEFORE INSERT OR UPDATE OF status%'))
) AS y(name, ok);
-- md5(prosrc) ต่อฟังก์ชัน (เทียบ scripts/ops/migration-function-md5.reference.txt ด้วย verify-migration-versions.sh)
SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='scan_jobs' AND column_name='free_access_kind') AS has_kind \gset
\if :has_kind
SELECT 'state' AS kind, 'free_access_kind=' || free_access_kind AS name, count(*) AS n
FROM public.scan_jobs WHERE free_access_kind LIKE 'bonus%' GROUP BY free_access_kind ORDER BY 2;
\endif
